#include "NativeColorsRuntime.generated.h"
#include <LVUI/NativeWidgetColors.h>
#include "../src/Widgets/WidgetState.h"
#include <iostream>
#include <stdexcept>
#include <thread>
using namespace ii;
void check(bool v,const char* text){if(!v)throw std::runtime_error(text);}
template<class T>T take(core::Result<T> r){if(!r){if(r.error().cause)std::rethrow_exception(r.error().cause);throw std::runtime_error(r.error().message);}return std::move(*r);}
void good(core::Result<void> r){if(!r){if(r.error().cause)std::rethrow_exception(r.error().cause);throw std::runtime_error(r.error().message);}}
struct Fixture final {
    using View=lvui_generated::NativeColorsRuntime;
    std::shared_ptr<gui::detail::WidgetState> state=std::make_shared<gui::detail::WidgetState>([](runtime::Task t){t();});
    gui::Widget host;std::shared_ptr<View::Scope> scope;
    Fixture(){host=take(state->content_host({},"root",{800,600}));good(host.set_content([&](gui::WidgetBuilder& w){return View::build(w,{}, {},&scope);}));}
    ~Fixture(){state->close();}
    std::vector<gui::Widget> find(std::string id){std::vector<gui::Widget> result;for(const auto& node:take(state->snapshots()))if(node.id==id||node.id.ends_with("/"+id))result.push_back(take(state->find(node.id)));return result;}
    gui::Widget one(std::string id){auto items=find(id);check(items.size()==1,"Expected one native color widget");return items.front();}
    gui::WidgetColor ink(std::string id){return take(one(id).snapshot()).foreground_color.value();}
};
void structure(){Fixture f;check(f.ink("live")==gui::WidgetColor{.2,.4,.6,.8}&&f.ink("hex")==gui::WidgetColor{1,0,0,128/255.},"Initial Color did not reach native widget");check(NativeColorModel::live==1&&NativeColorPrivate::live==2,"Color inputs duplicated backends");for(auto w:f.find("privateLabel"))check(take(w.snapshot()).foreground_color==gui::WidgetColor{0,1,0,1},"A color input replaced a shadowing private model");}
void updates(){Fixture f;auto live=f.one("live");auto before=take(live.snapshot());f.scope->backend_0.ink.set({.9,.3,.1,.7});check(f.ink("live")==gui::WidgetColor{.9,.3,.1,.7}&&take(f.one("alpha").snapshot()).text=="0.7","Reactive SDK Color or channel did not update");for(auto w:f.find("paintLabel"))check(take(w.snapshot()).foreground_color==f.ink("live"),"Typed Color forwarding lost its source");check(take(live.snapshot()).id==before.id&&take(live.snapshot()).font_size==before.font_size&&take(live.snapshot()).text==before.text&&f.scope->backend_0.file_revision.get()==0,"Color update rebuilt identity, changed label metrics or file state");}
void snapshots(){Fixture f;auto initial=f.ink("initial");f.scope->backend_0.ink.set({1,0,0,1});check(f.ink("initial")==initial&&f.ink("live")!=initial,"Static Color followed its source");for(auto w:f.find("fixedLabel"))check(take(w.snapshot()).foreground_color==initial,"A child Static Color changed");f.scope->backend_0.ready.set(false);check(NativeColorPrivate::live==1,"Color scope did not retire");f.scope->backend_0.ready.set(true);int red=0;for(auto w:f.find("fixedLabel"))if(take(w.snapshot()).foreground_color==gui::WidgetColor{1,0,0,1})++red;check(red==1&&NativeColorPrivate::live==2,"Remounted Color scope did not capture a fresh snapshot");}
void variables(){Fixture f;const gui::WidgetColor changed{.1,.2,.3,.4};good(lvui::native::assign_value(f.scope->value_localInk,changed));check(f.ink("local")==changed,"Mutable Color did not update its widget");bool bad=false;try{good(lvui::native::assign_value(f.scope->value_localInk,gui::WidgetColor{2,0,0,1}));}catch(...){bad=true;}check(bad&&f.ink("local")==changed&&f.scope->value_localInk.get()==changed,"Invalid Color assignment replaced valid state");Fixture::View unattached;check(!unattached.set_localInk(changed),"Unattached Color setter bypassed lifetime gate");}
void functions(){Fixture f;check(f.ink("sample")==gui::WidgetColor{.5,0,.5,1},"Native Color function result was not converted");f.scope->backend_0.amount.set(.25);check(f.ink("sample")==gui::WidgetColor{.25,0,.75,1},"Color function arguments did not remain reactive");f.scope->backend_0.ink.set({1,0,0,1});check(take(f.one("description").snapshot()).text=="High"&&f.scope->backend_0.file_revision.get()==0,"Native Color function argument or read-only state contract failed");}
void errors(){Fixture f;const auto old=f.ink("live"),old_hex=f.ink("hex");f.scope->backend_0.ink.set({2,0,0,1});f.scope->backend_0.hex.set("bad");check(f.ink("live")==old&&f.ink("hex")==old_hex,"Invalid source destroyed last valid native Color");f.scope->backend_0.ink.set({0,0,1,1});f.scope->backend_0.hex.set("#00ff00");check(f.ink("live")==gui::WidgetColor{0,0,1,1}&&f.ink("hex")==gui::WidgetColor{0,1,0,1},"Color bindings did not recover");}
void primitives(){Fixture f;auto label=f.one("live");const auto before=take(label.snapshot());good(label.set_label_color(gui::WidgetColor{1,0,0,1}));check(!label.set_label_color(gui::WidgetColor{2,0,0,1}),"Widget accepted invalid Color");good(label.set_label_color(std::nullopt));const auto after=take(label.snapshot());check(!after.foreground_color&&after.text==before.text&&after.font_size==before.font_size,"Color setter replaced label content or metrics");core::ErrorCode code=core::ErrorCode::failed;std::thread t([&]{auto r=label.set_label_color(gui::WidgetColor{});if(!r)code=r.error().code;});t.join();check(code==core::ErrorCode::wrong_executor,"Color setter accepted a foreign execution domain");}
void lifetime(){Fixture f;auto label=f.one("live");std::weak_ptr<Fixture::View::Scope> old=f.scope;f.state->close();f.scope.reset();check(old.expired()&&NativeColorModel::live==0&&NativeColorPrivate::live==0&&!label.set_label_color(gui::WidgetColor{}),"Color activation retained objects or admitted stale updates");}
void rollback(){Fixture f;auto old=f.one("live");const auto before=take(old.snapshot());NativeColorModel::bad_initial=true;std::shared_ptr<Fixture::View::Scope> candidate;auto result=f.host.set_content([&](gui::WidgetBuilder& w){return Fixture::View::build(w,{}, {},&candidate);});candidate.reset();NativeColorModel::bad_initial=false;check(!result&&take(old.snapshot()).id==before.id&&f.ink("live")==before.foreground_color&&NativeColorModel::live==1&&NativeColorPrivate::live==2,"Invalid Color candidate replaced the valid view or leaked objects");f.scope->backend_0.ink.set({0,0,1,1});check(f.ink("live")==gui::WidgetColor{0,0,1,1},"Color rollback disconnected the old view");}
void drawing(){
    lvui::native::WidgetPanelColors style{gui::WidgetColor{.5,0,0,.25},gui::WidgetColor{0,0,1,.5},1,8};
    const auto drawing=take(lvui::native::panel_color_drawing({.size={160,80}},style));
    check(drawing->panels.size()==2&&drawing->panels.front().bounds==gui::Rect{0,0,160,80}&&std::abs(drawing->panels[0].top.red-lvui::native::linear_color_channel(.5))<1e-6&&drawing->panels[0].top.alpha==.25f&&drawing->panels[1].stroke_width==1,"Panel paint did not retain bounds, linear RGB, independent alpha and stroke");
    lvui::native::PanelColorPainter painter;painter.set_colors(style);auto first=take(painter({.size={160,80}}));auto same=take(painter({.size={160,80},.hovered=true}));check(first==same,"Unchanged paint data allocated another drawing");
    painter.set_colors(style);check(take(painter({.size={160,80}}))==first,"Identical colors invalidated the drawing cache");
    check(take(painter({.size={180,80}}))!=first,"Resized panel retained the old drawing extent");
    core::ErrorCode foreign=core::ErrorCode::failed;std::thread worker([&]{auto r=painter({.size={160,80}});if(!r)foreign=r.error().code;});worker.join();check(foreign==core::ErrorCode::wrong_executor,"Panel painter admitted foreign-domain cache access");
    style.border.reset();check(!lvui::native::panel_color_drawing({.size={160,80}},style),"Panel paint accepted a border width without its color");
}
int main(int argc,char** argv){try{std::string s=argc>1?argv[1]:"structure";if(s=="structure")structure();else if(s=="updates")updates();else if(s=="snapshots")snapshots();else if(s=="variables")variables();else if(s=="functions")functions();else if(s=="errors")errors();else if(s=="primitives")primitives();else if(s=="lifetime")lifetime();else if(s=="rollback")rollback();else if(s=="drawing")drawing();else throw std::runtime_error("Unknown native Color widget test");std::cout<<"Native Color widget "<<s<<" passed without a window\n";}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
